def analysis_detail_page(record_id):
    """Render one stored analysis only when it belongs to the authenticated user."""
    ar=_lang()=="ar"
    row=advanced_features.get_user_analysis(_data_user_id(), record_id)
    if not row:
        abort(404)
    from html import escape
    result=row.get('result') or {}
    risk=(result.get('risk_level') or row.get('urgency') or 'low').lower()
    risk_map={
      'low':('منخفض' if ar else 'Low risk','low'),
      'medium':('يحتاج متابعة' if ar else 'Needs follow-up','medium'),
      'high':('عاجل' if ar else 'Urgent','high'),
      'urgent':('عاجل' if ar else 'Urgent','high'),
    }
    risk_label,risk_cls=risk_map.get(risk,(escape(str(risk)),'medium'))
    syms=''.join('<span class="sym-chip">%s</span>'%escape(str(x)) for x in (row.get('symptoms') or [])) or '<span>—</span>'
    dq=result.get('data_quality') or {}
    dq_html=''
    if isinstance(dq,dict) and dq.get('score') is not None:
        score=max(0,min(100,int(round(float(dq.get('score') or 0)))))
        level=escape(str(dq.get('level_label') or dq.get('level') or ''))
        dq_html=f'''<section class="detail-card"><div class="section-head"><h2>📊 {'اكتمال المعلومات' if ar else 'Information completeness'}</h2><b>{score}% · {level}</b></div><div class="detail-progress"><span style="width:{score}%"></span></div><p class="muted">{'يقيس هذا اكتمال المعلومات المتاحة للتحليل فقط، وليس احتمال مرض أو دقة تشخيص.' if ar else 'This measures information completeness only, not disease probability or diagnostic accuracy.'}</p></section>'''
    xai=result.get('explainability') or {}
    xai_html=''
    if isinstance(xai,dict) and xai:
        factors=[]
        for f in (xai.get('factors') or [])[:8]:
            if not isinstance(f,dict): continue
            label=escape(str(f.get('label') or f.get('feature') or '—'))
            influence=escape(str(f.get('influence_label') or f.get('influence') or ''))
            reason=escape(str(f.get('detail') or f.get('explanation') or f.get('reason') or ''))
            src=f.get('source_ref') if isinstance(f.get('source_ref'),dict) else {}
            surl=str(src.get('reference_url') or src.get('official_url') or '')
            stitle=str((src.get('reference_title_ar') if ar else src.get('reference_title_en')) or src.get('source_name') or src.get('organization') or '')
            src_link=(f'<a href="{escape(surl)}" target="_blank" rel="noopener noreferrer">📚 {escape(stitle)}</a>' if surl.startswith(('https://','http://')) and stitle else '')
            factors.append(f'<li><b>{label}</b><span>{influence}</span><small>{reason}{(" · "+src_link) if src_link else ""}</small></li>')
        if factors:
            xai_html=f'''<details class="detail-card xai-detail"><summary>🔍 {'لماذا ظهر هذا التقييم؟' if ar else 'Why this assessment?'}</summary><p class="muted">{'يعرض هذا العوامل التي ساهمت في قواعد السلامة والمطابقة المعرفية الفعلية، وليس أسبابًا طبية مؤكدة.' if ar else 'This shows factors that contributed to the actual safety and knowledge-matching logic, not confirmed medical causes.'}</p><ul>{''.join(factors)}</ul><p class="notice">{'العوامل المعروضة لا تؤكد تشخيصًا ولا تحدد سبب الأعراض.' if ar else 'The factors shown do not confirm a diagnosis or identify the cause of symptoms.'}</p></details>'''
    match_cards=[]
    for m in (result.get('knowledge_matches') or [])[:5]:
        if not isinstance(m,dict):
            continue
        cname=escape(str(m.get('name_ar') if ar else m.get('name_en') or ''))
        matched_names=[]
        for sx in (m.get('matched_symptoms') or []):
            if isinstance(sx,dict):
                val=sx.get('name_ar') if ar else sx.get('name_en')
                if val: matched_names.append(escape(str(val)))
        explanation=escape(str(m.get('description') or ''))
        src=m.get('explanation_source') or ((m.get('sources') or [None])[0] if m.get('sources') else None)
        src_html=''
        if isinstance(src,dict):
            surl=str(src.get('reference_url') or src.get('official_url') or '')
            stitle=str((src.get('reference_title_ar') if ar else src.get('reference_title_en')) or src.get('source_name') or src.get('organization') or '')
            if surl.startswith(('https://','http://')) and stitle:
                source_scope=str(src.get("source_scope") or "")
                src_label=("مرجع داعم للسياق" if ar else "Supporting context source") if source_scope=="symptom_context_fallback" else ("مرجع هذا التفسير" if ar else "Source for this explanation")
                src_html=f'<div class="direct-source">📚 {src_label}: <a href="{escape(surl)}" target="_blank" rel="noopener noreferrer">{escape(stitle)}</a></div>' 
        why=(('الأعراض المتوافقة: ' if ar else 'Matching symptoms: ')+('، ' if ar else ', ').join(matched_names)) if matched_names else explanation
        if matched_names and explanation:
            why += '<br><small>'+explanation+'</small>'
        match_cards.append(f'<article class="detail-match"><b>{cname}</b><p>{why}</p>{src_html}</article>')
    if match_cards:
        poss_html=f'<section class="detail-card"><h2>🩺 {"الاحتمالات المعلوماتية" if ar else "Informational possibilities"}</h2><div class="detail-match-list">{"".join(match_cards)}</div></section>'
    else:
        poss=escape(str(result.get('possible_conditions') or ''))
        poss_html=f'<section class="detail-card"><h2>🩺 {"الاحتمالات المعلوماتية" if ar else "Informational possibilities"}</h2><p>{poss}</p></section>' if poss else ''
    sources=[]
    for src in (result.get('medical_sources') or []):
        if not isinstance(src,dict): continue
        name=escape(str(src.get('source_name') or src.get('name') or src.get('organization') or 'Source'))
        url=str(src.get('official_url') or src.get('url') or '')
        link=f'<a href="{escape(url)}" target="_blank" rel="noopener noreferrer">{name}</a>' if url.startswith(('https://','http://')) else name
        sources.append(f'<li>{link}</li>')
    sources_html=f'''<section class="detail-card"><h2>📚 {'المصادر الطبية' if ar else 'Medical Sources'}</h2><ul class="source-list">{''.join(sources)}</ul></section>''' if sources else ''
    date=escape(str(row.get('timestamp') or '—'))[:19].replace('T',' ')
    duration=escape(str(row.get('duration') or '—')); severity=escape(str(row.get('severity') if row.get('severity') is not None else '—'))
    edit_url=('/ar/chat' if ar else '/en/chat')+f"?reanalyze={int(record_id)}&edit=1&from=history"
    body=f'''
    <main class="analysis-detail-shell">
      <div class="detail-nav"><a href="/history">← {'العودة للسجل' if ar else 'Back to history'}</a><a class="detail-edit-link" href="{edit_url}">✏️ {'تعديل إجاباتي' if ar else 'Edit answers'}</a></div>
      <section class="detail-hero"><div><span class="eyebrow">🩺 {'نتيجة التقييم' if ar else 'Assessment Result'}</span><h1>{date}</h1></div><span class="risk-pill {risk_cls}">{risk_label}</span></section>
      <section class="detail-card"><h2>{'الأعراض التي أدخلتها' if ar else 'Reported symptoms'}</h2><div class="sym-list">{syms}</div><div class="mini-grid"><div><small>{'المدة' if ar else 'Duration'}</small><b>{duration}</b></div><div><small>{'الشدة' if ar else 'Severity'}</small><b>{severity}</b></div></div></section>
      {dq_html}{poss_html}{xai_html}{sources_html}
      <section class="detail-card notice"><b>⚠️ {'تنبيه' if ar else 'Important notice'}</b><p>{'هذه المعلومات للتوعية ولا تُعد تشخيصًا طبيًا أو بديلًا عن استشارة الطبيب.' if ar else 'This information is for educational purposes and is not a medical diagnosis or a substitute for professional medical advice.'}</p></section>
    </main>
    <style>.analysis-detail-shell{{max-width:900px;margin:auto;display:grid;gap:14px}}.detail-nav{{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap}}.detail-nav a{{color:var(--v2-blue);font-weight:700}}.detail-edit-link{{padding:9px 12px;border:1px solid var(--v2-line);border-radius:11px;background:#fff;text-decoration:none}}.detail-hero,.detail-card{{background:#fff;border:1px solid var(--v2-line);border-radius:20px;padding:clamp(18px,3vw,24px);box-shadow:var(--v2-shadow)}}.detail-hero{{display:flex;justify-content:space-between;align-items:center;gap:18px}}.eyebrow{{color:var(--v2-blue);font-weight:800}}.risk-pill{{padding:7px 11px;border-radius:999px;font-size:12px;font-weight:800}}.risk-pill.low{{background:var(--v2-green-bg);color:var(--v2-green)}}.risk-pill.medium{{background:#FFF6DB;color:#8A6400}}.risk-pill.high{{background:#FDECEC;color:var(--v2-red)}}.sym-list{{display:flex;flex-wrap:wrap;gap:8px}}.sym-chip{{background:var(--v2-sky);border:1px solid var(--v2-line);border-radius:999px;padding:7px 10px}}.mini-grid{{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}}.mini-grid>div{{background:var(--v2-bg);border-radius:12px;padding:12px;display:grid;gap:4px}}.mini-grid small,.xai-detail small{{color:var(--v2-muted)}}.detail-progress{{height:9px;background:#EAF0F4;border-radius:999px;overflow:hidden}}.detail-progress span{{display:block;height:100%;background:var(--v2-blue);border-radius:999px}}.section-head{{display:flex;justify-content:space-between;gap:14px}}.xai-detail summary{{cursor:pointer;font-weight:800;font-size:18px}}.xai-detail li{{display:grid;grid-template-columns:1fr auto;gap:6px;padding:10px 0;border-bottom:1px solid var(--v2-line)}}.xai-detail li small{{grid-column:1/-1}}.source-list{{display:grid;gap:8px}}.detail-match-list{{display:grid;gap:10px}}.detail-match{{border:1px solid var(--v2-line);border-radius:14px;padding:14px;background:#FBFDFE}}.detail-match p{{margin:7px 0;line-height:1.75}}.direct-source{{font-size:12.5px;color:var(--v2-muted);margin-top:8px}}.direct-source a{{font-weight:800;color:var(--v2-blue)}}.notice{{background:#F8FBFE}}@media(max-width:600px){{.detail-hero,.section-head{{align-items:flex-start;flex-direction:column}}.mini-grid{{grid-template-columns:1fr}}}}</style>
    '''
    return _page('نتيجة التحليل' if ar else 'Analysis Result', body)


def bind(namespace):
    """Inject the webapp helpers this module needs (proxies, resolved lazily on every call)."""
    missing = [n for n in DEPS if n not in namespace]
    if missing:
        raise RuntimeError("pagelib.pages_html: missing dependencies %s" % missing)
    g = globals()
    for n in DEPS:
        g[n] = _inject.dependency(namespace, n)
